import hmac, hashlib, os
def verify_rzp(order_id: str, payment_id: str, sig: str):
    sec = os.environ.get('RAZORPAY_SECRET', 'dev')
    exp = hmac.new(sec.encode(), f'{order_id}|{payment_id}'.encode(), hashlib.sha256).hexdigest()
    if hmac.compare_digest(exp, sig):
        return {'status': 'paid'}
    return {'status': 'rejected'}

